function decN(n){const k=n%100,m=n%10;return n+' '+((k<11||k>14)&&m===1?'публикация':(k<11||k>14)&&m>=2&&m<=4?'публикации':'публикаций');}
let DEC_QUERY='',DEC_WEEK='',DEC_NET='tg',DEC_ANCHOR='';
const DEC_PLATS=['Все','YouTube','ВК','Telegram','Instagram','Менеджеры'];
function decPlatform(r){if(['TG компании','TG Романа','TG Кирилла'].includes(r.channel))return'Telegram';if(['TG Екатерины','TG Оксаны'].includes(r.channel))return'Менеджеры';if(['VK','VK Клипы'].includes(r.channel))return'ВК';return'Instagram';}
function decLabel(ch){return({'TG компании':'Юнитрамп · канал компании','TG Романа':'Роман Сотников','TG Кирилла':'Кирилл Шувалов','TG Екатерины':'Екатерина Тюкавкина','TG Оксаны':'Оксана Журман',VK:'Публикации ВК','VK Клипы':'ВК Клипы',Instagram:'Лента Instagram','IG Reels':'Instagram Reels'})[ch]||ch;}
function decCount(p){return p==='Все'?DEC_POSTS.length:DEC_POSTS.filter(r=>decPlatform(r)===p).length;}
function decEsc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function decFmt(n){return n==null?'—':new Intl.NumberFormat('ru-RU').format(n);}
function decAgg(rr,key){let known=rr.map(x=>x.metrics?.[key]).filter(x=>x!=null);return known.length?known.reduce((a,b)=>a+b,0):null;}
function decKpis(rr){return '<div class="kpis"><div class="kpi"><b>'+rr.length+'</b><span>публикаций</span></div><button class="kpi d6kpi '+(st.s==='v'?'selected':'')+'" data-s="v" aria-label="Сортировать по просмотрам"><b>'+decFmt(decAgg(rr,'views'))+'</b><span>просмотров ↗</span></button><button class="kpi d6kpi '+(st.s==='i'?'selected':'')+'" data-s="i" aria-label="Сортировать по взаимодействиям"><b>'+decFmt(decAgg(rr,'interactions'))+'</b><span>взаимодействий ↗</span></button></div>';}
function decSort(rr){let key=st.s==='v'?'views':st.s==='i'?'interactions':null;return rr.slice().sort((a,b)=>{let delta=key?((b.metrics?.[key]??-1)-(a.metrics?.[key]??-1)):0;return delta||(a.date+' '+a.time).localeCompare(b.date+' '+b.time)||a.id.localeCompare(b.id);});}
function decJump(id){const r=DEC_POSTS.find(x=>x.id===id);if(!r)return;st.p=decPlatform(r);st.f=r.channel;DEC_QUERY='';DEC_WEEK='';st.net='tg';DEC_ANCHOR=id;render();}
function decSummary(){
 const rr=DEC_POSTS;
 let h='<section class="s"><h2>Декабрь · месяц 3 <span class="muted">· 01–31.12.2026</span></h2>'+decKpis(rr)+'<p class="muted d6note">План на декабрь. Просмотры и взаимодействия заполняются после публикации.</p></section>';
 h+='<section class="s"><h2>По площадкам <span class="muted">· нажми на строку, чтобы открыть</span></h2><div class="tw"><table><thead><tr><th>Площадка</th><th class="n">Публикаций</th><th class="n">Просмотры</th><th class="n">Взаимодействия</th><th class="n">Среднее</th></tr></thead><tbody>';
 for(const p of ['Telegram','ВК','Instagram','Менеджеры']){const rows=rr.filter(x=>decPlatform(x)===p);h+='<tr class="go" data-p="'+p+'"><td><b>'+p+'</b></td><td class="n">'+rows.length+'</td><td class="n">'+decFmt(decAgg(rows,'views'))+'</td><td class="n">'+decFmt(decAgg(rows,'interactions'))+'</td><td class="n">—</td></tr>';}
 h+='<tr class="tot"><td>Итого</td><td class="n">'+rr.length+'</td><td class="n">'+decFmt(decAgg(rr,'views'))+'</td><td class="n">'+decFmt(decAgg(rr,'interactions'))+'</td><td></td></tr></tbody></table></div></section>';
 h+='<section class="s"><h2>По каналам <span class="muted">· статистика каждого канала отдельно</span></h2><div class="tw"><table><thead><tr><th>Канал</th><th class="n">Публикаций</th><th class="n">Просмотры</th><th class="n">Взаимодействия</th></tr></thead><tbody>';
 for(const ch of ['TG компании','TG Романа','TG Кирилла','TG Екатерины','TG Оксаны']){const rows=rr.filter(x=>x.channel===ch);h+='<tr class="go" data-dec-channel="'+ch+'"><td><b>'+decEsc(decLabel(ch))+'</b></td><td class="n">'+rows.length+'</td><td class="n">'+decFmt(decAgg(rows,'views'))+'</td><td class="n">'+decFmt(decAgg(rows,'interactions'))+'</td></tr>';}
 h+='</tbody></table></div></section><section class="s"><h2>Все публикации <span class="muted">· '+rr.length+'</span></h2><div class="tools">'+sortTools()+'</div><div class="d6list">';
 for(const r of decSort(rr))h+='<button class="li d6jump" data-dec-id="'+r.id+'"><span class="d">'+r.date.slice(-2)+'.12</span><span class="pl"><span class="tag">'+decEsc(decLabel(r.channel))+'</span></span><span class="d6listtitle">'+decEsc(r.title)+' <span class="muted">· '+r.id+'</span></span><span class="v">'+decFmt(r.metrics?.views)+' <small>просм.</small> · '+decFmt(r.metrics?.interactions)+' <small>взаим.</small></span></button>';
 return h+'</div></section>';
}
function decMedia(r,alt){const items=(alt?r.instagram_media:r.media_items)||[];if(!items.length)return'';
 const imgs=items.filter(m=>m.kind!=='video');let h='';
 if(imgs.length){h+='<div class="d6gallery" role="region" aria-label="Медиа '+r.id+'"><div class="d6track" tabindex="0">'+imgs.map((m,i)=>'<figure><a href="'+decEsc(m.file)+'" target="_blank" rel="noopener"><img loading="lazy" src="'+decEsc(m.file)+'" alt="'+decEsc(r.title)+' · '+(i+1)+'"></a><figcaption>'+decEsc(m.caption||'')+' <a href="'+decEsc(m.file)+'" download>Скачать'+(imgs.length>1?' '+(i+1):'')+'</a></figcaption></figure>').join('')+'</div>'+(imgs.length>1?'<div class="d6gallerynav"><button data-gallery-prev aria-label="Предыдущий слайд">←</button><span>'+imgs.length+' фото / слайда · листайте</span><button data-gallery-next aria-label="Следующий слайд">→</button></div>':'')+'</div>';}
 for(const m of items.filter(m=>m.kind==='video'))h+='<div class="d6video"><video controls muted playsinline preload="none" poster="'+decEsc(m.poster)+'" src="'+decEsc(m.file)+'"></video><div class="d6downloads"><a href="'+decEsc(m.file)+'" download>Скачать видео</a><a href="'+decEsc(m.poster)+'" download>Скачать обложку</a></div></div>';
 return h;
}
function decPoll(r){if(!r.poll)return'';const p=r.poll,q='poll-q-'+r.id,o='poll-o-'+r.id;return '<details class="d7poll"><summary>Вопрос, варианты и настройки опроса</summary><div id="'+q+'"><b>'+decEsc(p.question)+'</b></div><div id="'+o+'">'+p.options.map(v=>decEsc(v)).join('\n')+'</div><p><small>Анонимный опрос · '+(p.multiple_answers?'Несколько ответов':'Один ответ')+'</small></p><div class="d5buttons"><button data-dec-copy="'+q+'">Скопировать вопрос</button><button data-dec-copy="'+o+'">Скопировать варианты</button></div></details>';}
function decCard(r){const alt=DEC_NET==='ig'&&r.instagram_media?.length,mx=DEC_NET==='max'&&r.max_text,id='d6-'+r.id;return '<article class="d5card" data-dec-card data-dec-week="'+Math.min(5,Math.floor((Number(r.date.slice(-2))-1)/7)+1)+'" id="'+decEsc(r.id)+'"><div class="pstat"><b>'+decEsc(r.id)+'</b><span>'+r.date.slice(-2)+'.12 · '+r.time+' ЕКБ</span><span class="tag">'+decEsc(alt?'Instagram':mx?'Макс':decLabel(r.channel))+'</span><span><b>'+decFmt(r.metrics?.views)+'</b> просм.</span><span><b>'+decFmt(r.metrics?.interactions)+'</b> взаим.</span></div><div class="d6cardbody"><h2>'+decEsc(r.title)+'</h2><div class="d5format">'+decEsc(alt?'Instagram · адаптация':mx?'Макс · тот же пост':r.format)+'</div>'+decMedia(r,alt)+'<div class="d5text" id="'+id+'">'+(alt?r.instagram_html:mx?r.max_html:r.text_html)+'</div>'+decPoll(r)+'<div class="d5buttons"><button onclick="cp(\''+id+'\',this)">Скопировать с оформлением</button><button onclick="cp(\''+id+'\',this,true)">Обычный текст</button></div>'+(r.first_comment?'<details class="d6comment"><summary>Первый комментарий</summary><div id="'+id+'-comment">'+decEsc(r.first_comment)+'</div><button onclick="cp(\''+id+'-comment\',this,true)">Скопировать комментарий</button></details>':'')+'</div></article>';}
function viewDecember(M){
 if(st.p==='Все')return decSummary();
 let all=DEC_POSTS.filter(r=>decPlatform(r)===st.p),channels=[...new Set(all.map(x=>x.channel))];
 const aliases={'Канал Романа':'TG Романа','Канал Антона':'TG компании','Канал Кирилла':'TG Кирилла'};st.f=aliases[st.f]||st.f;if(!channels.includes(st.f))st.f='Все';
 let rows=all.filter(r=>st.f==='Все'||r.channel===st.f);const personal=st.f!=='Все'&&rows.some(r=>r.instagram_media?.length);
 DEC_NET=personal&&['ig','max'].includes(st.net)?st.net:'tg';
 let h='<section class="s"><h2>'+decEsc(st.f==='Все'?st.p:decLabel(st.f))+' <span class="muted">· Декабрь · 01–31.12.2026</span></h2>'+decKpis(rows)+'<div class="tools" style="margin-top:16px">'+sortTools()+'</div>';
 if(channels.length>1)h+='<div class="seg d6channels">'+['Все',...channels].map(ch=>'<button class="'+(st.f===ch?'on':'')+'" data-f="'+decEsc(ch)+'">'+(ch==='Все'?'Все каналы':decEsc(decLabel(ch)))+'</button>').join('')+'</div>';
 if(personal)h+='<div class="seg d6network"><button class="'+(DEC_NET==='tg'?'on':'')+'" data-dec-net="tg">Telegram</button><button class="'+(DEC_NET==='ig'?'on':'')+'" data-dec-net="ig">Instagram</button><button class="'+(DEC_NET==='max'?'on':'')+'" data-dec-net="max">Макс</button></div>';
 h+='<div class="d5filters"><label><span class="sr-only">Поиск по постам</span><input id="dec-query" type="search" placeholder="Найти пост, тему или объект" value="'+decEsc(DEC_QUERY)+'" oninput="decSearch(this.value)"></label><select aria-label="Неделя" onchange="decWeek(this.value)">'+[['','Весь декабрь'],['1','01–07 декабря'],['2','08–14 декабря'],['3','15–21 декабря'],['4','22–28 декабря'],['5','29–31 декабря']].map(([v,t])=>'<option value="'+v+'" '+(DEC_WEEK===v?'selected':'')+'>'+t+'</option>').join('')+'</select><span id="dec-found">'+decN(rows.length)+'</span></div></section>';
 if(!rows.length)return h+'<section class="s"><div class="empty">Публикаций на этой площадке пока нет.</div></section>';
 writeHash();return h+decSort(rows).map(decCard).join('')+'<p id="dec-empty" class="d5empty" hidden>По этим условиям постов нет.</p>';
}
function decFilter(){let n=0;document.querySelectorAll('[data-dec-card]').forEach(a=>{const show=(!DEC_WEEK||a.dataset.decWeek===DEC_WEEK)&&(!DEC_QUERY||a.innerText.toLocaleLowerCase('ru').includes(DEC_QUERY.toLocaleLowerCase('ru')));a.hidden=!show;if(show)n++;});const el=document.getElementById('dec-found');if(el)el.textContent=decN(n);const empty=document.getElementById('dec-empty');if(empty)empty.hidden=n>0;if(DEC_ANCHOR){document.getElementById(DEC_ANCHOR)?.scrollIntoView({block:'start'});DEC_ANCHOR='';}}
function decSearch(v){DEC_QUERY=v;decFilter();}function decWeek(v){DEC_WEEK=v;decFilter();}
document.addEventListener('click',e=>{const t=e.target.closest('[data-dec-id],[data-dec-channel],[data-dec-net],[data-gallery-prev],[data-gallery-next]');if(!t)return;e.preventDefault();if(t.dataset.decId){decJump(t.dataset.decId);return;}if(t.dataset.decChannel){const r=DEC_POSTS.find(r=>r.channel===t.dataset.decChannel);st.p=decPlatform(r);st.f=r.channel;st.net='tg';DEC_QUERY='';DEC_WEEK='';render();scrollTo(0,0);}if(t.dataset.decNet){DEC_NET=t.dataset.decNet;st.net=DEC_NET;render();}if(t.hasAttribute('data-gallery-prev')||t.hasAttribute('data-gallery-next')){let track=t.closest('.d6gallery').querySelector('.d6track');track.scrollBy({left:(t.hasAttribute('data-gallery-prev')?-1:1)*track.clientWidth,behavior:'smooth'});}});
document.addEventListener('click',e=>{if(MONTHS[st.m]?.key!=='2026-12')return;const t=e.target.closest('[data-p],[data-f]');if(t){DEC_QUERY='';DEC_WEEK='';st.net='tg';}},true);

document.addEventListener('click',e=>{const b=e.target.closest('[data-dec-copy]');if(b){e.preventDefault();cp(b.dataset.decCopy,b,true);}});
